import java.util.*;
public class CF375B {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalLines = Integer.parseInt(scanner.nextLine());
        String inputString = scanner.next().toLowerCase();
        String originalString = inputString;
        char[] characters = inputString.toCharArray();
        StringBuilder sb = new StringBuilder(originalString);
        Stack<Character> stack = new Stack<>();
        for (char c : characters) {
            stack.push(c);
        }
        List<Integer> bracketPositions = new ArrayList<>();
        for (int i = 0; i < characters.length; i++) {
            if (characters[i] == '(' || characters[i] == ')') {
                stack.pop();
                bracketPositions.add(i);
            }
        }
        TreeMap<Integer, Integer> pairsMap = new TreeMap<>();
        for (int i = 0; i < bracketPositions.size(); i += 2) {
            pairsMap.put(bracketPositions.get(i), bracketPositions.get(i + 1));
        }
        List<Integer> removeIndices = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : pairsMap.entrySet()) {
            int startIdx = entry.getKey();
            int endIdx = entry.getValue();
            for (int i = startIdx; i <= endIdx; i++) {
                removeIndices.add(i);
            }
        }
        List<Integer> removalSet = new ArrayList<>(removeIndices);
        char[] filteredChars = new char[characters.length - removalSet.size()];
        char[] replacedChars = new char[filteredChars.length];
        int fi = 0, ri = 0;
        for (int i = 0; i < characters.length; i++) {
            if (!removalSet.contains(i)) {
                filteredChars[fi++] = characters[i];
            }
        }
        boolean toggleFlag = true;
        for (int i = 0; i < characters.length; i++) {
            if (removalSet.contains(i)) {
                if (characters[i] == '(' || characters[i] == ')' || characters[i] == '_') {
                    if (toggleFlag) {
                        replacedChars[ri++] = ' ';
                        toggleFlag = false;
                    }
                } else {
                    replacedChars[ri++] = characters[i];
                    toggleFlag = true;
                }
            }
        }
        StringBuilder finalStrBuilder = new StringBuilder();
        for (char c : replacedChars) {
            finalStrBuilder.append(c);
        }
        String[] partsAfter = finalStrBuilder.toString().split(" ");
        List<Integer> lengthAfter = new ArrayList<>();
        for (String p : partsAfter) {
            String trimmed = p.trim();
            if (trimmed.length() != 0) {
                lengthAfter.add(trimmed.length());
            }
        }
        String replacedStr = inputString.replaceAll("\\(.*?\\) ?", " ").replace("_", " ");
        String[] partsBefore = replacedStr.split(" ");
        List<Integer> lengthBefore = new ArrayList<>();
        for (String p : partsBefore) {
            String trimmed = p.trim();
            if (trimmed.length() != 0) {
                lengthBefore.add(trimmed.length());
            }
        }
        Collections.sort(lengthAfter);
        int maxLength = lengthAfter.size() == 0 ? 0 : lengthAfter.get(lengthAfter.size() - 1);
        System.out.print(maxLength + " " + lengthBefore.size());
    }
}
